import { cursor } from './stores/cursor';
import { difficulty } from './stores/difficulty';
import { gamePaused } from './stores/game';
import { grid, userGrid, invalidCells, setStoreEnhancer } from './stores/grid';
import { timer } from './stores/timer';
import { hints } from './stores/hints';
import { enhanceGridStoreWithDomain } from '../../domain/StoreEnhancer.js';
import { get } from 'svelte/store';

const storeEnhancer = enhanceGridStoreWithDomain(userGrid, grid, invalidCells);
setStoreEnhancer(storeEnhancer);

export function startNew(diff) {
  difficulty.set(diff);
  const initialGrid = (() => {
    grid.generate(diff);
    return get(grid);
  })();

  storeEnhancer.initializeDomain(initialGrid);

  cursor.reset();
  timer.reset();
  hints.reset();

  location.hash = '';
}

export function startCustom(sencode) {
  difficulty.setCustom();
  const initialGrid = (() => {
    grid.decodeSencode(sencode);
    return get(grid);
  })();

  storeEnhancer.initializeDomain(initialGrid);

  cursor.reset();
  timer.reset();
  hints.reset();
}

export function pauseGame() {
  timer.stop();
  gamePaused.set(true);
}

export function resumeGame() {
  timer.start();
  gamePaused.set(false);
}

export function undo() {
  storeEnhancer.undo();
}

export function redo() {
  storeEnhancer.redo();
}

export function canUndo() {
  return storeEnhancer.canUndo();
}

export function canRedo() {
  return storeEnhancer.canRedo();
}

export function getCandidateHint() {
  return storeEnhancer.getCandidateHint();
}

export function getNextStepHint() {
  return storeEnhancer.getNextStepHint();
}

export function enterExploreMode() {
  return storeEnhancer.enterExploreMode();
}

export function commitExplore() {
  return storeEnhancer.commitExplore();
}

export function discardExplore() {
  return storeEnhancer.discardExplore();
}

export function rollbackExploreToStart() {
  return storeEnhancer.rollbackExploreToStart();
}

export function getExploreStatus() {
  return storeEnhancer.getExploreStatus();
}

export function getGameInstance() {
  return storeEnhancer.getGameInstance();
}

export default {
  startNew,
  startCustom,
  pause: pauseGame,
  resume: resumeGame,
  undo,
  redo,
  canUndo,
  canRedo,
  getCandidateHint,
  getNextStepHint,
  enterExploreMode,
  commitExplore,
  discardExplore,
  rollbackExploreToStart,
  getExploreStatus,
  getGameInstance
};
